mapper.select:
SELECT PRO.* FROM ( SELECT PPC.COMPANY_ID , PPC.PLI_CONTRACT_ID, PPC.POSTLOAN_INSPECTION_ID, PPC.BP_ID, PPC.REMAIN_AMOUNT, PPC.GUARANTOR_NAME, HBM.BP_NAME, PPC.PROJECT_ID, PPC.RATE_VALID_FROM, FP.PROJECT_NAME, PPC.LEASE_TERM, PPC.CONTRACT_TYPE, FC.CONTRACT_NUMBER, FC.CONTRACT_NAME, FC.APPROVAL_NUMBER, PPC.HOST_NAME, PPC.CO_ORGANIZER, PPC.UNIT_NAME, PPC.PROJECT_ASSISTANT, PPC.EMPLOYEE_ID, PPC.FINANCE_AMOUNT, PPC.CONTRACT_ID, PPC.ENABLE_FLAG, PPC.DESCRIPTION, HDT.DESCRIPTION AS BUSINESS_TYPE FROM PLM_PLI_CONTRACT PPC JOIN FCT_CONTRACT FC ON FC.CONTRACT_ID=PPC.CONTRACT_ID JOIN FCT_PROJECT FP ON FC.PROJECT_ID=FP.PROJECT_ID JOIN HLS_BP_MASTER HBM ON HBM.BP_ID= PPC.BP_ID LEFT JOIN HLS_BUSINESS_TYPE HDT on fc.BUSINESS_TYPE = HDT.BUSINESS_TYPE AND HDT.DOCUMENT_CATEGORY =fc.DOCUMENT_CATEGORY WHERE PPC.CONTRACT_TYPE='FCT_CONTRACT'
UNION
SELECT PPC.COMPANY_ID , PPC.PLI_CONTRACT_ID, PPC.POSTLOAN_INSPECTION_ID, PPC.BP_ID, PPC.REMAIN_AMOUNT, PPC.GUARANTOR_NAME, HBM.BP_NAME, PPC.PROJECT_ID, PPC.RATE_VALID_FROM, FP.PROJECT_NAME, PPC.LEASE_TERM, PPC.CONTRACT_TYPE, FC.CONTRACT_NUMBER, FC.CONTRACT_NAME, FP.APPROVAL_NUMBER, PPC.HOST_NAME, PPC.CO_ORGANIZER, PPC.UNIT_NAME, PPC.PROJECT_ASSISTANT, PPC.EMPLOYEE_ID, PPC.FINANCE_AMOUNT, PPC.CONTRACT_ID, PPC.ENABLE_FLAG, PPC.DESCRIPTION, HDT.DESCRIPTION AS BUSINESS_TYPE FROM PLM_PLI_CONTRACT PPC JOIN CON_CONTRACT FC ON FC.CONTRACT_ID=PPC.CONTRACT_ID JOIN PRJ_PROJECT FP ON FC.PROJECT_ID=FP.PROJECT_ID JOIN HLS_BP_MASTER HBM ON HBM.BP_ID= PPC.BP_ID LEFT JOIN HLS_BUSINESS_TYPE HDT on fc.BUSINESS_TYPE = HDT.BUSINESS_TYPE AND HDT.DOCUMENT_CATEGORY =fc.DOCUMENT_CATEGORY WHERE PPC.CONTRACT_TYPE='CON_CONTRACT' ) PRO WHERE PRO.POSTLOAN_INSPECTION_ID=#{postloanInspectionId}
